import { BadRequestException } from '@nestjs/common';
import { parseText } from '../../common/field-parsers';
import { parseCityStateZip } from '../../common/personal-info.validation';
import { parseCarePreferences } from '../care-preferences/care-preferences.validation';
import type {
  JobDetails,
  JobLocation,
  JobPostInput,
  JobTextRequestInput,
} from './jobs.types';

/**
 * Public job id (`jobs.jobId`): 16 lowercase hex characters, generated by
 * the database. Checked before querying so malformed ids are a 400.
 */
export const JOB_ID_REGEX = /^[0-9a-f]{16}$/;

export const isJobId = (value: string): boolean => JOB_ID_REGEX.test(value);

export const JOB_TITLE_MIN_LENGTH = 5;
export const JOB_TITLE_MAX_LENGTH = 100;
export const JOB_DESCRIPTION_MIN_LENGTH = 20;
export const JOB_DESCRIPTION_MAX_LENGTH = 2000;

const isRecord = (value: unknown): value is Record<string, unknown> =>
  Boolean(value) && typeof value === 'object' && !Array.isArray(value);

function requireObject(payload: unknown): Record<string, unknown> {
  if (!isRecord(payload)) {
    throw new BadRequestException({
      code: 'VALIDATION_ERROR',
      message: 'Payload must be an object',
    });
  }
  return payload;
}

/**
 * Location + care details shared by the job post and the text generator.
 * `details` uses the exact `PUT /seeker/care-preferences` shape and rules, so
 * a job can never hold answers the profile would reject (and vice versa).
 */
function parseLocationAndDetails(
  body: Record<string, unknown>,
  errors: string[],
  today: Date,
): { location: JobLocation | null; details: JobDetails | null } {
  const location = parseCityStateZip(body, errors);

  if (!isRecord(body.details)) {
    errors.push('details is required');
    return { location, details: null };
  }

  const detailErrors: string[] = [];
  const details = parseCarePreferences(body.details, detailErrors, today);
  errors.push(...detailErrors.map((error) => `details.${error}`));

  return { location, details };
}

function validationError(errors: string[]) {
  return new BadRequestException({
    code: 'VALIDATION_ERROR',
    message: 'Invalid job post',
    errors,
  });
}

/**
 * `POST /seeker/jobs`: `{ title, description, city, state, postalCode,
 * details }`. Every problem is reported at once as `400 VALIDATION_ERROR`.
 */
export function validateJobPostPayload(
  payload: unknown,
  today = new Date(),
): JobPostInput {
  const body = requireObject(payload);
  const errors: string[] = [];

  const title = parseText(body.title, 'title', errors, {
    required: true,
    min: JOB_TITLE_MIN_LENGTH,
    max: JOB_TITLE_MAX_LENGTH,
  });
  const description = parseText(body.description, 'description', errors, {
    required: true,
    min: JOB_DESCRIPTION_MIN_LENGTH,
    max: JOB_DESCRIPTION_MAX_LENGTH,
  });
  const { location, details } = parseLocationAndDetails(body, errors, today);

  if (errors.length > 0 || !title || !description || !location || !details) {
    throw validationError(errors);
  }

  return { title, description, ...location, details };
}

/**
 * `POST /seeker/jobs/draft/text`: the job post without its text
 * (`{ city, state, postalCode, details }`), to write a new title and
 * description for edited details.
 */
export function validateJobTextPayload(
  payload: unknown,
  today = new Date(),
): JobTextRequestInput {
  const body = requireObject(payload);
  const errors: string[] = [];
  const { location, details } = parseLocationAndDetails(body, errors, today);

  if (errors.length > 0 || !location || !details) {
    throw validationError(errors);
  }

  return { ...location, details };
}
